Given an array arr[] of positive integers. All numbers occur an even number of times except one number which occurs an odd number of times. Examples : Input : arr[]= [1, 2, 3, 2, 3, 1, 3]Output : 3Input : arr[] = [5, 7, 2, 7, 5, 2, 5]Output : 5Try It YourselfTable of Content[Naive Approach] Using Nested Loop[Another Approach]Using Hashing[Expected Approach] Using Bit Manipulation[Naive Approach] Using Nested LoopA Simple Solution is to run two nested loops. The outer loop picks all elements one by one and the inner loop counts the number of occurrences of the element picked by the outer loop. 
            C++

    #include<iostream>
#include <vector>
using namespace std;

// Function to find the element 
// occurring odd number of times
int getOddOccurrence(vector<int>&arr, int n)
{
    for (int i = 0; i < n ; i++) {

        int count = 0;

        for (int j = 0; j < n; j++)
        {
            if (arr[i] == arr[j])
                count++;
        }
        if (count % 2 != 0)
            return arr[i];
    }
    return -1;
}


int main()
    {
       vector<int>arr { 2, 3, 5, 4, 5, 2,
                      4, 3, 5, 2, 4, 4, 2 };
        int n = arr.size();
        cout << getOddOccurrence(arr, n);

        return 0;
    }


