    #include <iostream>
#include <vector>
using namespace std;

// Function to find element occurring odd number of times
int getOddOccurrence(vector<int>& ar)
{
    int res = 0; 
    for (int i = 0; i < ar.size(); i++)     
        res ^= ar[i];

    return res;
}

int main()
{
    vector<int> ar = {2, 3, 5, 4, 5, 2, 4, 3, 5, 2, 4, 4, 2};

    // Function calling
    cout << getOddOccurrence(ar);

    return 0;
}


